    "explanation": "**[풀이]**\n\n**핵심 개념:** 다항함수의 극한은 직접 대입으로 구합니다.\n$$\\lim_{x \\to a} f(x) = f(a)$$\n\n**Step 1. 직접 대입**\n$f(x) = 3x^2 - 5x + 1$은 다항함수이므로 $x = 2$를 직접 대입합니다.\n$$f(2) = 3(2)^2 - 5(2) + 1$$\n\n**Step 2. 계산**\n$$= 3 \\times 4 - 10 + 1 = 12 - 10 + 1 = 3$$\n\n**Step 3. 검증**\n다항함수는 모든 실수에서 연속이므로 극한값 = 함수값입니다. $x = 1.9$일 때 $f(1.9) = 3(3.61) - 9.5 + 1 = 10.83 - 9.5 + 1 = 2.33$, $x = 2.1$일 때 $f(2.1) = 3(4.41) - 10.5 + 1 = 13.23 - 10.5 + 1 = 3.73$으로 3에 수렴하는 것을 확인할 수 있습니다. ✓\n\n**∴ 답: 3**\n\n**💡 포인트:** 다항함수, 유리함수(분모≠0), 무리함수(정의역 내) 등 연속함수의 극한은 직접 대입이 가장 빠른 방법입니다.",
