    "explanation": "**[풀이]**\n\n**핵심 개념:** 최고차항의 계수비를 이용합니다. 전개하지 않고 각 인수의 최고차항만 추출해도 됩니다.\n\n**Step 1. 최고차항 추출**\n- 분자: $(2x+1)(3x-2)$의 최고차항 → $2x \\cdot 3x = 6x^2$\n- 분모: $(x+3)(x-1)$의 최고차항 → $x \\cdot x = x^2$\n\n**Step 2. 계수비**\n분자·분모 모두 2차이므로 최고차 계수의 비가 극한값입니다.\n$$\\lim_{x \\to \\infty} \\frac{6x^2 + \\cdots}{x^2 + \\cdots} = \\frac{6}{1} = 6$$\n\n**Step 3. 검증 — 전개로 확인**\n분자: $(2x+1)(3x-2) = 6x^2 - 4x + 3x - 2 = 6x^2 - x - 2$\n분모: $(x+3)(x-1) = x^2 + 2x - 3$\n$x^2$으로 나누면: $\\frac{6 - \\frac{1}{x} - \\frac{2}{x^2}}{1 + \\frac{2}{x} - \\frac{3}{x^2}} \\to \\frac{6}{1} = 6$ ✓\n\n**∴ 답: ④ 6**\n\n③ 5는 $2 + 3$으로 잘못 계산한 것이고, ② 3은 한쪽 인수의 계수만 본 오답입니다.\n\n**💡 포인트:** 인수 형태의 분수에서는 전개하지 않고 각 인수의 최고차항끼리 곱하여 최고차항을 빠르게 파악할 수 있습니다.",
