    "explanation": "**[풀이]**\n\n**핵심 개념:** 분모가 0으로 갈 때 극한값이 유한하면 분자도 반드시 0이어야 합니다.\n$$\\lim_{x \\to a} g(x) = 0 \\text{이고 } \\lim_{x \\to a} \\frac{f(x)}{g(x)} = L \\text{ (유한)} \\Rightarrow \\lim_{x \\to a} f(x) = 0$$\n\n**Step 1. 분모 극한 확인**\n$x \\to 1$일 때 분모 $x - 1 \\to 0$입니다.\n\n**Step 2. 극한값이 유한하므로 분자도 0**\n$\\lim_{x \\to 1} \\frac{f(x)}{x-1} = 5$ (유한)이므로, $\\lim_{x \\to 1} f(x) = 0$이어야 합니다.\n\n**Step 3. 다항함수의 연속성**\n$f(x)$가 다항함수이므로 $\\lim_{x \\to 1} f(x) = f(1)$입니다.\n따라서 $f(1) = 0$입니다.\n\n**Step 4. 검증**\n예를 들어 $f(x) = 5(x-1)$이면 $\\frac{f(x)}{x-1} = 5$이고, $f(1) = 0$입니다. ✓\n\n**∴ 답: 0**\n\n**💡 포인트:** '분모 → 0, 극한 유한 → 분자 → 0'은 미정계수 결정 문제에서 가장 자주 쓰이는 핵심 조건입니다. 반드시 기억하세요.",
