    "answer": 1,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 분모 → 0이고 극한 유한 → 분자 → 0 조건을 이용하여 미정계수를 결정합니다.\n\n**Step 1. 분자 → 0 조건**\n$x \\to 1$일 때 분모 $x - 1 \\to 0$이고 극한값 10이 유한이므로\n$$f(1) = a + b - 3 = 0 \\quad \\therefore a + b = 3 \\quad \\cdots (1)$$\n\n**Step 2. 인수분해**\n$f(1) = 0$이므로 $f(x) = ax^2 + bx - 3$은 $(x-1)$을 인수로 가집니다.\n$f(x) = a(x-1)(x - r)$ 형태 (단, $ar = 3$, 전개하면 계수 비교 가능)\n\n조립제법 또는 직접 나눔: $f(x) = (x-1)(ax + (a+b))$\n확인: $(x-1)(ax + a + b) = ax^2 + (a+b)x - ax - (a+b) = ax^2 + bx - (a+b)$\n$-(a+b) = -3$이므로 $a+b = 3$ ✓ (식 (1)과 일치)\n\n**Step 3. 극한 계산**\n$$\\lim_{x \\to 1} \\frac{(x-1)(ax + a + b)}{x-1} = \\lim_{x \\to 1} (ax + a + b) = a + a + b = 2a + b$$\n이것이 10이므로: $2a + b = 10 \\quad \\cdots (2)$\n\n**Step 4. 연립방정식**\n$(1): a + b = 3$, $(2): 2a + b = 10$\n$(2) - (1): a = 7$, $b = 3 - 7 = -4$\n$a + b = 7 + (-4) = 3$\n\n**∴ 답: ② 3**\n\n**💡 포인트:** 이 유형은 ① 분자 → 0 조건으로 첫 번째 식, ② 약분 후 극한 = 주어진 값으로 두 번째 식을 세워 연립합니다.",
