    "explanation": "**[풀이]**\n\n**핵심 개념:** $\\infty - \\infty$ 부정형에서 무리식 - 무리식은 유리화합니다.\n\n**Step 1. 유리화**\n$$\\frac{(\\sqrt{x^2+3x} - \\sqrt{x^2-x})(\\sqrt{x^2+3x} + \\sqrt{x^2-x})}{\\sqrt{x^2+3x} + \\sqrt{x^2-x}}$$\n$$= \\frac{(x^2+3x) - (x^2-x)}{\\sqrt{x^2+3x} + \\sqrt{x^2-x}} = \\frac{4x}{\\sqrt{x^2+3x} + \\sqrt{x^2-x}}$$\n\n**Step 2. $x$로 나누기** ($x > 0$)\n$$= \\frac{4}{\\sqrt{1+\\frac{3}{x}} + \\sqrt{1-\\frac{1}{x}}}$$\n\n**Step 3. 극한 계산**\n$x \\to \\infty$이면\n$$= \\frac{4}{\\sqrt{1} + \\sqrt{1}} = \\frac{4}{2} = 2$$\n\n**∴ 답: ② 2**\n\n③ 3은 분모의 한 항만 고려한 오답, ⑤ 발산은 부정형 처리를 하지 않은 결과입니다.\n\n**💡 포인트:** $\\sqrt{x^2+ax} - \\sqrt{x^2+bx}$ 꼴의 극한값은 $\\frac{a-b}{2}$입니다. 여기서는 $\\frac{3-(-1)}{2} = 2$로 빠르게 구할 수 있습니다.",
