    "explanation": "**[풀이]**\n\n**핵심 개념:** **중간값 정리(Intermediate Value Theorem)**: 닫힌구간 $[a,b]$에서 연속인 함수 $f$에 대해, $f(a)$와 $f(b)$ 사이의 임의의 값 $k$에 대해 $f(c) = k$인 $c$가 $(a,b)$에 존재합니다.\n\n**Step 1. 조건 확인**\n- $f$는 $[0,3]$에서 연속 ✓\n- $f(0) = -2 < 0$, $f(3) = 4 > 0$이므로 부호가 바뀝니다.\n\n**Step 2. 중간값 정리 적용**\n$0$은 $f(0) = -2$와 $f(3) = 4$ 사이의 값이므로, $f(c) = 0$인 $c \\in (0,3)$이 적어도 하나 존재합니다.\n\n**Step 3. 오답 분석**\n- ① 롤의 정리: $f(a) = f(b)$일 때 $f'(c) = 0$인 $c$ 존재 (미분 관련)\n- ② 평균값 정리: $f'(c) = \\frac{f(b)-f(a)}{b-a}$인 $c$ 존재 (미분 관련)\n- ⑤ 샌드위치 정리: 극한의 대소 관계 정리\n\n**∴ 답: ③ 중간값 정리**\n\n**💡 포인트:** '연속 + 함수값의 부호 변화 → 근의 존재'는 중간값 정리의 대표적 응용입니다. 수능에서 근의 존재성 증명에 자주 출제됩니다.",
