    "explanation": "**[풀이]**\n\n**핵심 개념:** 분모 → 0인 점에서 연속이려면 분자도 0이 되어야 하고, 약분 후 극한값 = 함수값이어야 합니다.\n\n**Step 1. 분자 → 0 조건**\n$x = 1$에서 분모 $= 0$이고 극한값이 유한(= 5)이므로\n$$1 + a + b = 0 \\quad \\cdots (1)$$\n\n**Step 2. 인수분해**\n$f(1) = 0$이므로 $x^2 + ax + b = (x-1)(x-p)$ (최고차 계수 1)\n$(x-1)(x-p) = x^2 - (1+p)x + p$이므로\n$a = -(1+p)$, $b = p$ → $a + b = -(1+p) + p = -1$ → $1 + a + b = 0$ ✓\n\n**Step 3. 극한 = 5 조건**\n$$\\lim_{x \\to 1} \\frac{(x-1)(x-p)}{x-1} = \\lim_{x \\to 1}(x - p) = 1 - p = 5$$\n$$p = -4$$\n\n**Step 4. $a, b$ 결정**\n$b = p = -4$, $a = -(1 + (-4)) = 3$\n\n**Step 5. 답 계산 및 검증**\n$ab = 3 \\times (-4) = -12$\n\n$f(x) = \\frac{x^2+3x-4}{x-1} = \\frac{(x-1)(x+4)}{x-1} = x + 4$ ($x \\neq 1$)\n$\\lim_{x \\to 1}(x+4) = 5 = f(1)$ ✓\n\n**∴ 답: -12**\n\n**💡 포인트:** 유리함수의 연속화에서는 ① 분자 → 0 조건으로 인수분해 가능하게 만들고, ② 약분 후 극한값 = 함수값으로 나머지 미지수를 결정합니다.",
