    "explanation": "**[풀이]**\n\n**핵심 개념:** $|g(x)|$는 $g(x) = 0$인 점에서 미분불가능할 수 있습니다 (뾰족점).\n\n**Step 1. $g(x) = 0$인 점 찾기**\n$x^2 - 4 = 0$ → $x = 2$ 또는 $x = -2$\n\n**Step 2. 각 점에서 미분가능성 확인**\n$x = 2$: $g'(2) = 2(2) = 4 \\neq 0$이므로 $|g(x)|$는 $x = 2$에서 꺾입니다.\n좌미분: $\\lim_{x \\to 2^-} \\frac{|x^2-4| - 0}{x-2}$. $x < 2$이면 $x^2-4 < 0$이므로 $|x^2-4| = 4-x^2$.\n좌미분 $= \\lim_{x \\to 2^-} \\frac{4-x^2}{x-2} = \\lim_{x \\to 2^-} \\frac{-(x-2)(x+2)}{x-2} = -4$\n우미분 $= \\lim_{x \\to 2^+} \\frac{x^2-4}{x-2} = 4$\n좌미분 $\\neq$ 우미분 → $x = 2$에서 미분불가능\n\n$x = -2$: 마찬가지로 $g'(-2) = -4 \\neq 0$\n좌미분 = $\\lim_{x \\to -2^-} \\frac{x^2-4-0}{x-(-2)} = \\frac{(x-2)(x+2)}{x+2} \\to -4$\n우미분 = $\\lim_{x \\to -2^+} \\frac{-(x^2-4)}{x+2} = \\frac{(x-2)(x+2) \\cdot (-1)}{x+2} \\to 4$\n좌미분 $\\neq$ 우미분 → $x = -2$에서 미분불가능\n\n**Step 3. 다른 점 확인**\n$x \\neq \\pm 2$인 모든 점에서 $f(x)$는 다항함수의 합성이므로 미분가능합니다.\n\n**∴ 답: 2** ($x = -2$, $x = 2$에서 미분불가능)\n\n**💡 포인트:** $|g(x)|$에서 $g(a) = 0$이고 $g'(a) \\neq 0$이면 $x = a$에서 미분불가능(뾰족점)입니다. $g'(a) = 0$이면 미분가능할 수도 있습니다.",
