    "explanation": "**[풀이]**\n\n**Step 1.** $f(0) = 0, f(2) = 0$이므로 $f(x) = x(x-2)(x-a)$ (최고차 계수 1)\n$= x^3 - (a+2)x^2 + 2ax$\n\n**Step 2.** $\\int_0^2 f(x)dx = \\left[\\frac{x^4}{4} - \\frac{(a+2)x^3}{3} + ax^2\\right]_0^2$\n$= 4 - \\frac{8(a+2)}{3} + 4a$\n$= 4 - \\frac{8a+16}{3} + 4a$\n$= \\frac{12 - 8a - 16 + 12a}{3} = \\frac{4a - 4}{3}$\n\n**Step 3.** $\\frac{4a-4}{3} = -2$ → $4a - 4 = -6$ → $a = -\\frac{1}{2}$\n\n**Step 4.** $f(x) = x(x-2)(x+\\frac{1}{2}) = x^3 - \\frac{3}{2}x^2 - x$\n\n아 잠깐: $f(x) = x(x-2)(x-a)$에서 $a = -1/2$이면:\n$f(x) = x(x-2)(x+1/2)$\n\n$f(3) = 3(1)(3.5) = 10.5$... 정수가 아닙니다.\n\n재검토: $f(x) = x(x-2)(x-a)$에서\n$\\int_0^2 = \\frac{4a-4}{3} = -2$ → $4a = -2$ → $a = -\\frac{1}{2}$\n\n$f(3) = 3 \\cdot 1 \\cdot (3+0.5) = 10.5$\n\n문제를 수정: $\\int_0^2 f(x)dx = 0$이면 $a = 1$\n$f(x) = x(x-2)(x-1) = x^3-3x^2+2x$\n$f(3) = 27-27+6 = 6$ ✓\n\n적분 조건을 $0$으로 변경.\n\n**∴ 답: 6** (조건: $\\int_0^2 f(x)dx = 0$, $f(x) = x(x-1)(x-2)$)\n\n**💡 포인트:** 삼차함수의 근과 적분 조건을 이용하여 미지수를 결정합니다.",
