    "explanation": "**[풀이]**\n\n**Step 1.** $f'(x) = 3x^2-12 = 3(x-2)(x+2)$\n극대: $f(-2) = -8+24+a = 16+a$\n극소: $f(2) = 8-24+a = -16+a$\n$f(0) = a$\n\n**Step 2.** 양의 실근 2개 (음의 실근은 0개 또는 1개)\n\n$x > 0$ 영역에서 그래프: $f(0) = a$, 극소 $f(2) = a-16$, $f(x) \\to \\infty$ ($x \\to \\infty$)\n\n양의 실근이 2개: $f(2) = a-16 < 0$ (극소가 $x$축 아래)이고 $f(0) = a > 0$ (원점에서 양수)\n또는 $f(2) = 0$ ($a = 16$)이면 이중근 → 1개로 셈\n\n$0 < a < 16$이면 양의 실근 2개 (하나는 $(0,2)$, 하나는 $(2,\\infty)$)\n\n$x < 0$ 영역: $f(-2) = 16+a > 0$ ($a > 0$이므로), $f(x) \\to -\\infty$ ($x \\to -\\infty$)\n따라서 음의 실근 1개\n\n총 3개의 실근 중 양의 실근 2개\n\n$a = 16$: $f(2)=0$이고 $f(0)=16>0$ → 이중근, 양의 실근 1개 (2가 이중근)\n$a = 0$: $f(0) = 0$ → $x = 0$은 양이 아님, 양의 실근 1개\n\n따라서 $0 < a < 16$에서 양의 실근 2개 (?)\n\n재확인: $a = 1$, $f(x)=x^3-12x+1$\n$f(0)=1>0$, $f(2)=-15<0$, $f(4)=64-48+1=17>0$\n양의 근: $(0,2)$에 1개, $(2,4)$에 1개 → 2개 ✓\n$f(-4)=-64+48+1=-15<0$, $f(-2)=16+1=17>0$ → 음의 근: $(-\\infty,-4)$에 없고 $(-4,-2)$에 1개 → 총 3실근\n\n$a = 15$: $f(0)=15$, $f(2)=-1<0$, 양의 근 2개 ✓\n\n정수 $a$: $1, 2, \\ldots, 15$ → 15개\n\n답을 15로 수정.\n\n**∴ 답: 15**\n\n**💡 포인트:** 삼차함수의 그래프에서 양의 실근 개수는 $f(0)$과 극솟값의 부호로 결정됩니다.",
