    "problem": "실수 전체에서 미분가능한 함수 $f(x)$가 $f(x+y) = f(x) + f(y) + 3xy(x+y)$를 만족하고 $\\lim_{h \\to 0} \\dfrac{f(h)}{h} = 2$일 때, $f'(3)$의 값을 구하시오.",
