    "choices": null,
    "answer": 29,
    "explanation": "**[풀이]**\n\n**Step 1.** $x = y = 0$: $f(0) = 2f(0)$ → $f(0) = 0$\n\n**Step 2.** 미분의 정의로 $f'(x)$ 구하기\n$f'(x) = \\lim_{h\\to 0}\\frac{f(x+h)-f(x)}{h} = \\lim_{h\\to 0}\\frac{f(x)+f(h)+3xh(x+h)-f(x)}{h}$\n$= \\lim_{h\\to 0}\\left(\\frac{f(h)}{h}+3x(x+h)\\right) = 2 + 3x^2$\n\n**Step 3.** $f'(3) = 2 + 27 = 29$\n\n**∴ 답: 29**\n\n**💡 포인트:** 함수방정식에서 $f'(x)$를 미분의 정의로 직접 구합니다. $f(x) = 2x+x^3$임을 알 수 있습니다.",
