    "problem": "함수 $f(x) = \\begin{cases} \\dfrac{x^3 - 8}{x^2 - 4} & (x \\neq 2) \\\\\\\\ a & (x = 2) \\end{cases}$와 $g(x) = \\begin{cases} \\dfrac{\\sqrt{x+7} - 3}{x - 2} & (x \\neq 2) \\\\\\\\ b & (x = 2) \\end{cases}$에 대하여 $h(x) = f(x) \\cdot g(x)$가 $x = 2$에서 연속일 때, $60(a + b)$의 값을 구하시오.",
