    "answer": 190,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 곱함수 $h(x) = f(x) \\cdot g(x)$가 연속이려면 각 인수가 연속이어야 합니다.\n\n**Step 1. $f(x)$의 $x = 2$에서의 극한**\n$$\\frac{x^3 - 8}{x^2 - 4} = \\frac{(x-2)(x^2+2x+4)}{(x-2)(x+2)} = \\frac{x^2+2x+4}{x+2}$$\n$$\\lim_{x \\to 2} \\frac{x^2+2x+4}{x+2} = \\frac{4+4+4}{4} = 3$$\n따라서 $a = 3$\n\n**Step 2. $g(x)$의 $x = 2$에서의 극한 (유리화)**\n$$\\frac{\\sqrt{x+7}-3}{x-2} = \\frac{(x+7)-9}{(x-2)(\\sqrt{x+7}+3)} = \\frac{1}{\\sqrt{x+7}+3}$$\n$$\\lim_{x \\to 2} \\frac{1}{\\sqrt{9}+3} = \\frac{1}{6}$$\n따라서 $b = \\frac{1}{6}$\n\n**Step 3. 최종 계산**\n$$60(a+b) = 60\\left(3 + \\frac{1}{6}\\right) = 60 \\times \\frac{19}{6} = 190$$\n\n**∴ 답: 190**\n\n**💡 포인트:** 인수분해와 유리화를 동시에 활용하는 복합 연속성 문제입니다.",
