    "explanation": "**[풀이]**\n\n**핵심 개념:** 곡선 밖의 점에서 접선을 그을 때, 접점을 매개변수로 놓고 방정식을 세웁니다.\n\n**Step 1. 접점 $(t, t^3)$에서의 접선**\n기울기 $= 3t^2$이므로 접선: $y - t^3 = 3t^2(x - t)$, 즉 $y = 3t^2 x - 2t^3$\n\n**Step 2. $(2, 4)$를 지나는 조건**\n$$4 = 6t^2 - 2t^3$$\n$$t^3 - 3t^2 + 2 = 0$$\n$(t-1)(t^2 - 2t - 2) = 0$\n$t = 1$ 또는 $t = 1 \\pm \\sqrt{3}$\n\n**Step 3. 기울기의 합 (근과 계수)**\n각 기울기: $3t_i^2$\n기울기의 합 $= 3(t_1^2 + t_2^2 + t_3^2) = 3\\bigl[(t_1+t_2+t_3)^2 - 2(t_1t_2+t_2t_3+t_3t_1)\\bigr]$\n\n근과 계수: $t_1 + t_2 + t_3 = 3$, $t_1t_2 + t_2t_3 + t_3t_1 = 0$\n$$= 3(9 - 0) = 27$$\n\n**검증:** $3(1)^2 + 3(1+\\sqrt{3})^2 + 3(1-\\sqrt{3})^2 = 3 + 3(4+2\\sqrt{3}) + 3(4-2\\sqrt{3}) = 3 + 12 + 12 = 27$ ✓\n\n**∴ 답: ③ 27**\n\n**💡 포인트:** 접점의 $t$값에 대한 삼차방정식의 근과 계수의 관계를 활용하면 개별 근을 구하지 않고도 기울기의 합을 계산할 수 있습니다.",
