    "explanation": "**[풀이]**\n\n**핵심 개념:** 합성함수의 미분법 (연쇄법칙)을 적용합니다. $f(g(x)) = h(x)$이면 양변을 $x$에 대해 미분하면 $f'(g(x)) \\cdot g'(x) = h'(x)$입니다.\n\n**Step 1. 양변 미분**\n$f(x^3 + x) = e^x$의 양변을 $x$에 대해 미분하면\n$$f'(x^3 + x) \\cdot (3x^2 + 1) = e^x$$\n\n**Step 2. $f'(2)$를 구하기 위한 $x$ 값 찾기**\n$f'(2)$를 구하려면 $x^3 + x = 2$인 $x$를 찾아야 합니다.\n$x^3 + x = 2$에서 $x = 1$을 대입하면 $1 + 1 = 2$ ✓\n\n**Step 3. $x = 1$ 대입**\n$$f'(1^3 + 1) \\cdot (3 \\cdot 1^2 + 1) = e^1$$\n$$f'(2) \\cdot 4 = e$$\n$$f'(2) = \\frac{e}{4}$$\n\n**Step 4. 검증**\n$g(x) = x^3 + x$는 단조증가함수이므로 $g(x) = 2$의 해는 $x = 1$이 유일합니다. 연쇄법칙 적용 과정도 올바릅니다. ✓\n\n**∴ 답: ④ $\\dfrac{e}{4}$**\n\n**💡 포인트:** $f(g(x)) = h(x)$ 형태에서 $f'(a)$를 구하려면 먼저 $g(x) = a$인 $x$를 찾고, 그 $x$를 미분한 식에 대입합니다. 합성함수 미분법의 전형적인 유형입니다.",
