    "explanation": "**[풀이]**\n\n**핵심 개념:** $x \\to 0$일 때 $\\ln(1+x) \\sim x$, $\\sqrt{x+a} - \\sqrt{a}$는 유리화를 사용합니다.\n\n**Step 1. 부정형 확인**\n$x = 0$ 대입: 분자 $= \\ln 1 = 0$, 분모 $= \\sqrt{4} - 2 = 0$ → $\\frac{0}{0}$ 부정형\n\n**Step 2. 분모 유리화**\n$$\\frac{\\ln(x+1)}{\\sqrt{x+4} - 2} \\cdot \\frac{\\sqrt{x+4} + 2}{\\sqrt{x+4} + 2} = \\frac{\\ln(x+1) \\cdot (\\sqrt{x+4} + 2)}{(x+4) - 4} = \\frac{\\ln(x+1) \\cdot (\\sqrt{x+4} + 2)}{x}$$\n\n**Step 3. 극한 계산**\n$$\\lim_{x \\to 0} \\frac{\\ln(x+1)}{x} \\cdot (\\sqrt{x+4} + 2)$$\n\n$\\displaystyle\\lim_{x \\to 0} \\frac{\\ln(x+1)}{x} = 1$ (기본 극한)이고,\n$\\displaystyle\\lim_{x \\to 0} (\\sqrt{x+4} + 2) = \\sqrt{4} + 2 = 4$이므로\n\n$$= 1 \\times 4 = 4$$\n\n**Step 4. 검증**\n$x = 0.01$일 때: 분자 $= \\ln(1.01) \\approx 0.00995$, 분모 $= \\sqrt{4.01} - 2 \\approx 0.002499$, 비율 $\\approx 3.98 \\approx 4$ ✓\n\n**∴ 답: ④ 4**\n\n**💡 포인트:** $\\lim_{x \\to 0} \\frac{\\ln(1+x)}{x} = 1$은 수능에서 매우 자주 출제되는 기본 극한입니다. 무리식이 포함되면 유리화를 먼저 해야 합니다.",
