    "explanation": "**[풀이]**\n\n**핵심 개념:** 구분구적법으로 정적분으로 변환합니다. $\\displaystyle\\lim_{n \\to \\infty} \\frac{1}{n} \\sum_{k=1}^{n} f\\!\\left(\\frac{k}{n}\\right) = \\int_0^1 f(x)\\,dx$\n\n**Step 1. 정적분 변환**\n$\\frac{k}{n} = x$로 놓으면 $\\frac{1}{n} = dx$이고\n$$\\lim_{n \\to \\infty} \\frac{1}{n} \\sum_{k=1}^{n} \\sqrt{1 + 3 \\cdot \\frac{k}{n}} = \\int_0^1 \\sqrt{1 + 3x}\\,dx$$\n\n**Step 2. 치환적분**\n$u = 1 + 3x$로 놓으면 $du = 3\\,dx$, $dx = \\frac{du}{3}$\n$x = 0$일 때 $u = 1$, $x = 1$일 때 $u = 4$\n$$\\int_1^4 \\sqrt{u} \\cdot \\frac{du}{3} = \\frac{1}{3} \\int_1^4 u^{1/2}\\,du$$\n\n**Step 3. 적분 계산**\n$$= \\frac{1}{3} \\left[\\frac{2}{3} u^{3/2}\\right]_1^4 = \\frac{1}{3} \\cdot \\frac{2}{3} \\left(4^{3/2} - 1^{3/2}\\right) = \\frac{2}{9}(8 - 1) = \\frac{2}{9} \\times 7 = \\frac{14}{9}$$\n\n**Step 4. 검증**\n$\\frac{14}{9} \\approx 1.556$, $n = 1000$으로 수치 검산하면 약 $1.555$로 수렴합니다. ✓\n\n**∴ 답: ③ $\\dfrac{14}{9}$**\n\n**💡 포인트:** 구분구적법 → 정적분 변환은 수능 미적분 필수 유형입니다. $\\frac{1}{n} \\sum f(\\frac{k}{n})$ 형태를 보면 바로 $\\int_0^1 f(x)\\,dx$로 변환하세요.",
