    "problem": "함수 $f(x) = ae^{2x} + be^x + c$가 다음 조건을 만족시킨다.\n\n(가) $f(0) = 0$\n(나) $f'(0) = 0$\n(다) $\\displaystyle\\int_0^{\\ln 2} f(x)\\,dx = 3\\ln 2 - 2$\n\n$f(x)$의 역함수를 $g(x)$라 할 때, $\\displaystyle\\int_0^{f(\\ln 2)} g(x)\\,dx$의 값을 구하시오.",
