    "problem": "실수 전체의 집합에서 미분가능한 함수 $f(x)$의 역함수가 존재한다. 함수 $g(m)$이 $f$의 역함수와 관련된 조건을 만족시킬 때, $g(m)$이 불연속인 $m$의 개수를 구하시오.\n\n(가) $f(0) = 1$, $f'(0) = 2$\n(나) 모든 실수 $x$에 대하여 $f(x+1) = 3f(x)$\n(다) $0 \\leq x \\leq 1$에서 $f(x) = 2^x$",
