    "explanation": "**[풀이]**\n\n**핵심 개념:** 위치함수 $s(t)$를 미분하면 속도함수 $v(t) = s'(t)$를 얻습니다. 속도는 위치의 시간에 대한 변화율이므로 $v(t) = \\dfrac{ds}{dt}$입니다.\n\n**Step 1. 속도함수 구하기**\n위치함수 $s(t) = t^3 - 3t^2 + 2t$를 $t$에 대해 미분합니다.\n$$v(t) = s'(t) = 3t^2 - 6t + 2$$\n각 항을 미분하면: $(t^3)' = 3t^2$, $(-3t^2)' = -6t$, $(2t)' = 2$입니다.\n\n**Step 2. $t = 1$ 대입**\n$$v(1) = 3(1)^2 - 6(1) + 2 = 3 - 6 + 2 = -1$$\n\n**Step 3. 결과 해석**\n$v(1) = -1 < 0$이므로 $t = 1$에서 점 P는 음의 방향(왼쪽)으로 속력 1로 움직이고 있습니다. 참고로 $v(t) = 3t^2 - 6t + 2 = 0$을 풀면 $t = \\dfrac{6 \\pm \\sqrt{12}}{6} = 1 \\pm \\dfrac{\\sqrt{3}}{3}$에서 속도가 0이 되어 운동 방향이 바뀝니다.\n\n**Step 4. 검증**\n$s(0.99) = (0.99)^3 - 3(0.99)^2 + 2(0.99) = 0.970299 - 2.9403 + 1.98 = 0.009999$\n$s(1.01) = (1.01)^3 - 3(1.01)^2 + 2(1.01) = 1.030301 - 3.0603 + 2.02 = -0.009999$\n평균변화율 $= \\dfrac{-0.009999 - 0.009999}{0.02} = \\dfrac{-0.019998}{0.02} = -0.9999 \\approx -1$ ✓\n\n**∴ 답: $-1$**\n\n**💡 포인트:** 속도 = 위치함수의 도함수입니다. 속도의 부호가 양이면 양의 방향, 음이면 음의 방향으로 움직입니다. 속력은 속도의 절댓값 $|v(t)|$입니다.",
