    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** $\\dfrac{0}{0}$ 부정형에서 지수함수의 테일러 전개 $e^u = 1 + u + \\dfrac{u^2}{2!} + \\dfrac{u^3}{3!} + \\cdots$를 활용하여 분자의 최저차 항을 분석합니다.\n\n**Step 1. 부정형 확인**\n$x = 0$ 대입: 분자 $= e^0 - 1 - 0 = 0$, 분모 $= 0$ → $\\dfrac{0}{0}$ 부정형입니다.\n\n**Step 2. $e^{2x}$ 테일러 전개**\n$u = 2x$로 놓으면:\n$$e^{2x} = 1 + 2x + \\frac{(2x)^2}{2!} + \\frac{(2x)^3}{3!} + \\cdots = 1 + 2x + 2x^2 + \\frac{4x^3}{3} + \\cdots$$\n\n**Step 3. 분자 계산**\n$$e^{2x} - 1 - 2x = \\left(1 + 2x + 2x^2 + \\frac{4x^3}{3} + \\cdots\\right) - 1 - 2x = 2x^2 + \\frac{4x^3}{3} + \\cdots$$\n분자의 최저차 항은 $2x^2$입니다.\n\n**Step 4. 극한 계산**\n$$\\lim_{x \\to 0} \\frac{2x^2 + \\frac{4x^3}{3} + \\cdots}{x^2} = \\lim_{x \\to 0} \\left(2 + \\frac{4x}{3} + \\cdots\\right) = 2$$\n\n**Step 5. 로피탈 법칙으로 검증**\n$\\dfrac{0}{0}$ 부정형이므로 로피탈 법칙을 2회 적용합니다.\n1회: $\\lim_{x \\to 0} \\dfrac{2e^{2x} - 2}{2x} = \\lim_{x \\to 0} \\dfrac{2(e^{2x} - 1)}{2x}$ → 여전히 $\\dfrac{0}{0}$\n2회: $\\lim_{x \\to 0} \\dfrac{4e^{2x}}{2} = \\dfrac{4 \\cdot 1}{2} = 2$ ✓\n\n**Step 6. 수치 검증**\n$x = 0.1$: $\\dfrac{e^{0.2} - 1 - 0.2}{0.01} = \\dfrac{1.22140 - 1.2}{0.01} = \\dfrac{0.02140}{0.01} = 2.140 \\approx 2$ ✓\n$x = 0.01$: $\\dfrac{e^{0.02} - 1.02}{0.0001} = \\dfrac{1.02020 - 1.02}{0.0001} = \\dfrac{0.00020}{0.0001} = 2.001 \\approx 2$ ✓\n\n**∴ 답: ③ $2$**\n\n① 0은 분자가 $x^2$보다 고차라고 착각한 오답, ⑤ $\\frac{1}{2}$는 $e^x$의 전개를 $e^{2x}$ 대신 적용한 결과입니다.\n\n**💡 포인트:** $e^{ax} - 1 - ax \\sim \\dfrac{a^2 x^2}{2}$ ($x \\to 0$)은 자주 출제되는 공식입니다. 지수함수의 2차 이상 전개를 기억하면 빠르게 풀 수 있습니다.",
