    "explanation": "**[풀이]**\n\n**핵심 개념:** $x^x = e^{x \\ln x}$로 변환한 뒤, $x = 1 + h$ ($h \\to 0$)으로 치환하여 테일러 전개를 적용합니다. 또는 로피탈 법칙을 2회 적용합니다.\n\n**Step 1. 부정형 확인**\n$x = 1$ 대입: 분자 $= 1^1 - 1 = 0$, 분모 $= 0$ → $\\dfrac{0}{0}$ 부정형입니다.\n\n**Step 2. 로피탈 법칙 1회 적용**\n$f(x) = x^x - x$, $g(x) = (x-1)^2$로 놓으면\n$f'(x) = x^x(\\ln x + 1) - 1$, $g'(x) = 2(x-1)$\n$f'(1) = 1 \\cdot (0+1) - 1 = 0$, $g'(1) = 0$ → 여전히 $\\dfrac{0}{0}$ 부정형\n\n**Step 3. 로피탈 법칙 2회 적용**\n$x^x = e^{x\\ln x}$이므로 $(x^x)' = x^x(\\ln x + 1)$를 한 번 더 미분합니다.\n$f''(x) = \\dfrac{d}{dx}[x^x(\\ln x + 1) - 1] = x^x(\\ln x + 1)^2 + x^x \\cdot \\dfrac{1}{x}$\n$g''(x) = 2$\n$f''(1) = 1 \\cdot (0+1)^2 + 1 \\cdot 1 = 1 + 1 = 2$\n$$\\lim_{x \\to 1} \\frac{f(x)}{g(x)} = \\frac{f''(1)}{g''(1)} = \\frac{2}{2} = 1$$\n\n**Step 4. 테일러 전개로 검증**\n$x = 1+h$로 치환하면 $(1+h)\\ln(1+h) = (1+h)(h - \\dfrac{h^2}{2} + \\cdots) = h + \\dfrac{h^2}{2} + O(h^3)$\n$e^{h + h^2/2 + \\cdots} = 1 + (h + \\dfrac{h^2}{2}) + \\dfrac{(h+\\cdots)^2}{2} + \\cdots = 1 + h + \\dfrac{h^2}{2} + \\dfrac{h^2}{2} + \\cdots = 1 + h + h^2 + O(h^3)$\n분자: $(1+h+h^2+\\cdots) - (1+h) = h^2 + O(h^3)$\n$$\\lim_{h \\to 0} \\frac{h^2 + O(h^3)}{h^2} = 1$$ ✓\n\n**Step 5. 수치 검증**\n$x = 1.01$: $1.01^{1.01} = e^{1.01 \\times 0.00995} = e^{0.01005} \\approx 1.01010$\n분자 $\\approx 1.01010 - 1.01 = 0.000100$, 분모 $= 0.0001$, 비율 $= 1.0$ ✓\n$x = 1.001$: $1.001^{1.001} \\approx 1.001001$, 분자 $\\approx 0.000001$, 분모 $= 0.000001$, 비율 $= 1.0$ ✓\n\n**∴ 답: ④ $1$**\n\n③ $\\frac{1}{2}$는 $(1+h)\\ln(1+h)$의 $h^2$ 항을 $\\frac{h^2}{2}$만 취하고 $e^u$의 2차항 $\\frac{u^2}{2}$를 빠뜨린 오답입니다. ① $-\\frac{1}{2}$는 부호 착오입니다.\n\n**💡 포인트:** $x^x$는 $e^{x\\ln x}$로 변환하는 것이 정석입니다. 로피탈 법칙 2회 적용이 가장 깔끔하며, $f''(1) = [(\\ln x + 1)^2 + \\frac{1}{x}]_{x=1} = 2$임을 기억하면 빠르게 풀 수 있습니다.",
