    "answer": 2,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 합성함수의 관계에서 $f$를 직접 구한 뒤 미분하거나, 양변을 미분하여 연쇄법칙을 적용합니다.\n\n**방법 1: $f$ 직접 구하기**\n\n**Step 1. 치환으로 $f$ 파악**\n$t = x^2 + 1$로 놓으면 $x^2 = t - 1$ ($t \\geq 1$)입니다.\n우변을 $x^2$으로 정리하면:\n$$x^4 + 4x^2 + 3 = (x^2)^2 + 4(x^2) + 3 = (t-1)^2 + 4(t-1) + 3$$\n$$= t^2 - 2t + 1 + 4t - 4 + 3 = t^2 + 2t$$\n따라서 $f(t) = t^2 + 2t$입니다.\n\n**Step 2. 미분**\n$$f'(t) = 2t + 2$$\n\n**Step 3. $f'(2)$ 계산**\n$$f'(2) = 2(2) + 2 = 6$$\n\n**방법 2: 연쇄법칙 활용**\n\n$f(x^2+1) = x^4 + 4x^2 + 3$의 양변을 $x$에 대해 미분하면:\n$$f'(x^2+1) \\cdot 2x = 4x^3 + 8x$$\n$x \\neq 0$일 때 양변을 $2x$로 나누면:\n$$f'(x^2+1) = 2x^2 + 4$$\n$x^2 + 1 = 2$, 즉 $x = 1$을 대입하면:\n$$f'(2) = 2(1)^2 + 4 = 6$$\n\n**Step 4. 검증**\n$f(t) = t^2 + 2t$이므로 $f(x^2+1) = (x^2+1)^2 + 2(x^2+1) = x^4 + 2x^2 + 1 + 2x^2 + 2 = x^4 + 4x^2 + 3$ ✓\n$f'(2) = 2(2) + 2 = 6$ ✓\n\n**∴ 답: ③ $6$**\n\n② 4는 $f'(x^2+1) = 2x^2+4$에서 $x=0$을 잘못 대입한 오답, ④ 8은 연쇄법칙의 $2x$를 곱한 채로 답한 오류입니다.\n\n**💡 포인트:** $f(g(x)) = h(x)$ 꼴에서 $f$를 구하려면 $t = g(x)$로 치환하여 $x$를 $t$로 표현하거나, 양변 미분 후 연쇄법칙을 적용합니다. 두 방법 모두 능숙해야 합니다.",
