    "answer": 0,
    "explanation": "**[풀이]**\n\n**핵심 개념:** 삼차방정식 $f(x) = 0$이 서로 다른 세 실근을 가지려면 극댓값 > 0이고 극솟값 < 0이어야 합니다 (또는 직접 인수분해하여 근의 조건을 분석합니다).\n\n**Step 1. 직접 인수분해**\n$$f(x) = x^3 - 3ax = x(x^2 - 3a)$$\n$f(x) = 0$이면 $x = 0$ 또는 $x^2 = 3a$입니다.\n\n**Step 2. 세 실근 조건**\n$x = 0$은 항상 근입니다.\n$x^2 = 3a$가 0이 아닌 서로 다른 두 실근을 가지려면 $3a > 0$, 즉 $a > 0$이어야 합니다.\n이때 세 근은 $x = 0, \\, x = \\sqrt{3a}, \\, x = -\\sqrt{3a}$로 모두 다릅니다.\n\n**Step 3. 극값으로 검증**\n$f'(x) = 3x^2 - 3a = 0$에서 $x = \\pm\\sqrt{a}$ ($a > 0$일 때).\n- 극댓값: $f(-\\sqrt{a}) = -a\\sqrt{a} + 3a\\sqrt{a} = 2a\\sqrt{a} > 0$ ✓\n- 극솟값: $f(\\sqrt{a}) = a\\sqrt{a} - 3a\\sqrt{a} = -2a\\sqrt{a} < 0$ ✓\n극댓값 > 0이고 극솟값 < 0이므로 $x$축과 세 점에서 만납니다.\n\n**Step 4. $a \\leq 0$인 경우 확인**\n- $a = 0$: $f(x) = x^3$이므로 $x = 0$ (삼중근) → 서로 다른 세 근 ✗\n- $a < 0$: $x^2 = 3a < 0$이므로 실수 해가 없어 근은 $x = 0$ 하나뿐 → ✗\n\n**Step 5. 수치 검증**\n$a = 1$: $f(x) = x^3 - 3x = x(x-\\sqrt{3})(x+\\sqrt{3})$, 세 근 $0, \\pm\\sqrt{3}$ ✓\n$a = 4$: $f(x) = x(x^2 - 12)$, 세 근 $0, \\pm 2\\sqrt{3}$ ✓\n\n**∴ 답: ① $a > 0$**\n\n④ $a \\geq 0$은 $a = 0$일 때 삼중근이 되어 '서로 다른' 세 근 조건을 만족하지 않습니다. ⑤ $a \\neq 0$은 $a < 0$인 경우를 포함하는 오답입니다.\n\n**💡 포인트:** 삼차방정식의 실근 개수를 판별할 때는 (1) 인수분해 가능하면 직접 분해, (2) 불가능하면 극대·극소의 부호를 분석합니다. 극댓값 × 극솟값 < 0이면 서로 다른 세 실근을 가집니다.",
