    "problem": "직선 위를 움직이는 두 점 P, Q의 시각 $t$($t > 0$)에서의 위치가 각각 $x_P(t) = t^3$, $x_Q(t) = 12t$이다. 두 점의 속도가 같아지는 양수 $t$의 값은?",
