    "explanation": "**[풀이]**\n\n**핵심 개념:** 곱의 미분법: $(fg)' = f'g + fg'$\n\n**Step 1. 두 함수 설정**\n$g(x) = x + 1$, $h(x) = x^2 + 3$으로 놓으면 $f(x) = g(x) \\cdot h(x)$\n\n**Step 2. 각 함수의 도함수**\n$g'(x) = 1$, $h'(x) = 2x$\n\n**Step 3. $x = 1$ 대입하여 계산**\n$g'(1) = 1$, $h(1) = 1 + 3 = 4$\n$g(1) = 2$, $h'(1) = 2$\n$$f'(1) = 1 \\times 4 + 2 \\times 2 = 4 + 4 = 8$$\n\n**Step 4. 검증 (전개 후 미분)**\n$f(x) = x^3 + 3x + x^2 + 3 = x^3 + x^2 + 3x + 3$\n$f'(x) = 3x^2 + 2x + 3$\n$f'(1) = 3 + 2 + 3 = 8$ ✓\n\n**∴ 답: 8**\n\n**💡 포인트:** 주관식(구하시오)에서는 답만 정확히 계산하면 됩니다. 곱의 미분법은 전개하지 않고 바로 대입하는 것이 빠릅니다.",
