    "explanation": "**[풀이]**\n\n**핵심 개념:** $f'(x)$를 역미분(부정적분)하여 $f(x)$를 구합니다.\n\n**Step 1. $f(x)$ 구하기 (역미분)**\n$f'(x) = 8x^3 - 1$을 역미분하면\n$$f(x) = 2x^4 - x + C \\quad (C\\text{는 적분상수})$$\n\n**Step 2. 초기조건으로 $C$ 결정**\n$f(0) = 3$이므로\n$$2(0)^4 - 0 + C = 3 \\implies C = 3$$\n따라서 $f(x) = 2x^4 - x + 3$\n\n**Step 3. $f(2)$ 계산**\n$$f(2) = 2(2)^4 - 2 + 3 = 2(16) - 2 + 3 = 32 - 2 + 3 = 33$$\n\n**Step 4. 검증**\n$f'(x) = 8x^3 - 1$: $f'(x) = 2 \\cdot 4x^3 - 1 = 8x^3 - 1$ ✓\n$f(0) = 0 - 0 + 3 = 3$ ✓\n\n**∴ 답: 33**\n\n**💡 포인트:** $f'(x)$가 주어지면 역미분으로 $f(x) = \\int f'(x)\\,dx$를 구하되, 반드시 적분상수 $C$를 초기조건으로 결정해야 합니다.",
