    "explanation": "**[풀이]**\n\n**핵심 개념:** 곱의 미분법으로 $f'(1)$을 $a$에 대한 식으로 세운 뒤 풀기\n\n**Step 1. 곱의 미분법 설정**\n$g(x) = x^2 + 1$, $h(x) = x^2 + ax + 3$\n$g'(x) = 2x$, $h'(x) = 2x + a$\n$$f'(x) = g'(x)h(x) + g(x)h'(x)$$\n\n**Step 2. $x = 1$ 대입**\n$g'(1) = 2$, $h(1) = 1 + a + 3 = 4 + a$\n$g(1) = 2$, $h'(1) = 2 + a$\n$$f'(1) = 2(4 + a) + 2(2 + a) = 8 + 2a + 4 + 2a = 12 + 4a$$\n\n**Step 3. 조건 적용**\n$f'(1) = 32$이므로\n$$12 + 4a = 32$$\n$$4a = 20 \\implies a = 5$$\n\n**Step 4. 검증**\n$a = 5$일 때 $f(x) = (x^2 + 1)(x^2 + 5x + 3)$\n$f'(1) = 2(1 + 5 + 3) + 2(2 + 5) = 2(9) + 2(7) = 18 + 14 = 32$ ✓\n\n**∴ 답: 5**\n\n**💡 포인트:** 미정계수가 포함된 곱의 미분은 대입 후 방정식을 세워 풀면 됩니다. 전개할 필요 없이 곱의 미분법을 바로 적용하면 간단합니다.",
