    "explanation": "**[풀이]**\n\n**핵심 개념:** $f'(x)$를 역미분(부정적분)하여 $f(x)$를 구합니다.\n\n**Step 1. $f(x)$ 구하기 (역미분)**\n$f'(x) = 4x^3 - 2x$를 역미분하면\n$$f(x) = x^4 - x^2 + C \\quad (C\\text{는 적분상수})$$\n$(4x^3 \\to x^4$, $-2x \\to -x^2)$\n\n**Step 2. 초기조건으로 $C$ 결정**\n$f(0) = 3$이므로\n$$0 - 0 + C = 3 \\implies C = 3$$\n따라서 $f(x) = x^4 - x^2 + 3$\n\n**Step 3. $f(2)$ 계산**\n$$f(2) = (2)^4 - (2)^2 + 3 = 16 - 4 + 3 = 15$$\n\n**Step 4. 검증**\n$f'(x) = 4x^3 - 2x$ ✓, $f(0) = 0 - 0 + 3 = 3$ ✓\n\n**∴ 답: 15**\n\n**💡 포인트:** 역미분 시 $ax^n$의 역미분은 $\\frac{a}{n+1}x^{n+1}$입니다. $4x^3 \\to \\frac{4}{4}x^4 = x^4$, $-2x \\to \\frac{-2}{2}x^2 = -x^2$로 계산합니다.",
