    "problem": "기울기가 $8$이고 $y$절편이 양수인 직선이 곡선 $y = x^3 - 3x^2 - x + 2$에 접한다. 이 직선이 점 $(1, k)$를 지날 때, $k$의 값을 구하시오.",
