    "answer": 7,
    "explanation": "**[풀이]**\n\n**핵심 개념:** $g(x) = 2x^3 - 6x^2$으로 놓으면, $g(x) = -k$가 서로 다른 양의 실근 2개를 갖는 조건을 구합니다.\n\n**Step 1. $g(x)$의 극값 구하기**\n$g'(x) = 6x^2 - 12x = 6x(x - 2)$\n$g'(x) = 0$이면 $x = 0$ 또는 $x = 2$\n\n**Step 2. 극값 계산**\n극대: $g(0) = 0$ ($x = 0$)\n극소: $g(2) = 16 - 24 = -8$ ($x = 2$)\n\n**Step 3. 그래프 분석**\n$g(x) = 2x^2(x - 3)$이므로 $x = 0$(중근)과 $x = 3$에서 $g = 0$\n\n그래프의 형태:\n- $x < 0$: $g(x) < 0$\n- $x = 0$: $g = 0$ (극대)\n- $0 < x < 2$: $g(x) < 0$ (감소)\n- $x = 2$: $g = -8$ (극소)\n- $x > 3$: $g(x) > 0$ (증가)\n\n**Step 4. 서로 다른 양의 실근 2개 조건**\n$y = -k$ 수평선이 양의 영역($x > 0$)에서 $g(x)$와 정확히 2점에서 만나려면:\n$-8 < -k < 0$이어야 합니다.\n\n이 범위에서 $g(x) = -k$는 $x < 0$에서 1개, $0 < x < 2$에서 1개, $x > 2$에서 1개, 총 3개의 실근을 가지며, 이 중 양의 실근이 정확히 2개입니다.\n\n$-8 < -k < 0 \\implies 0 < k < 8$\n\n**Step 5. 정수 $k$의 개수**\n$k = 1, 2, 3, 4, 5, 6, 7$ → **7개**\n\n**Step 6. 검증 (경계값)**\n$k = 0$: $2x^3 - 6x^2 = 0 \\to 2x^2(x-3) = 0$ → 양의 실근: $x = 3$ 하나뿐 ✗\n$k = 8$: $2x^3 - 6x^2 + 8 = 0 \\to 2(x-2)^2(x+1) = 0$ → 양의 실근: $x = 2$ 하나뿐 ✗\n\n**∴ 답: 7**\n\n**💡 포인트:** 삼차방정식의 실근 개수 문제는 $y = f(x)$와 $y = c$의 교점 개수로 바꾸어 그래프로 분석합니다. '양의 실근'이라는 조건에 주의해야 합니다.",
